unsigned process_flac_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_read = 0;
    FLAC__StreamDecoder *decoder = psf->decoder;

    if (!decoder || !FLAC__stream_decoder_get_state(decoder))
        return 0;

    while (bytes_read < len) {
        FLAC__StreamDecoderState state = FLAC__stream_decoder_get_state(decoder);

        if (state == FLAC__STREAM_DECODER_END_OF_STREAM)
            break;

        if (state != FLAC__STREAM_DECODER_CONTINUE)
            continue;

        FLAC__byte buffer[len];
        unsigned bytes_to_read = (len - bytes_read) < len ? (len - bytes_read) : len;

        if (FLAC__stream_decoder_read(decoder, buffer, &bytes_to_read) != FLAC__STREAM_DECODER_READ_STATUS_CONTINUE) {
            if (FLAC__stream_decoder_get_state(decoder) != FLAC__STREAM_DECODER_END_OF_STREAM)
                continue;

            break;
        }

        memcpy(psf->data + bytes_read, buffer, bytes_to_read);
        bytes_read += bytes_to_read;
    }

    if (FLAC__stream_decoder_get_state(decoder) != FLAC__STREAM_DECODER_END_OF_STREAM && bytes_read < len)
        psf->decoder = NULL;

    return bytes_read;
}

unsigned flac_decode_audio_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    FLAC__uint64 pos = psf->filelength - psf->current;
    void *frame_ptr = psf->frame.buffer;

    if (psf->flac_decoder_state != FLAC__DECODER_OK && psf->flac_decoder_state != FLAC__DECODER_END_OF_STREAM) {
        psf_log_printf(psf, "FLAC decoder is in an error state: %d\n", psf->flac_decoder_state);
        frame_ptr = NULL;
    }

    if (frame_ptr != NULL && psf->frame.buffered > 0) {
        unsigned copy_len = SF_MIN(remaining, psf->frame.buffered);
        memcpy(psf->buffer + bytes_read, frame_ptr, copy_len);
        bytes_read += copy_len;
        remaining -= copy_len;
        psf->frame.buffered -= copy_len;
        psf->frame.buffer += copy_len;
    }

    while (remaining > 0 && psf->flac_decoder_state != FLAC__DECODER_END_OF_STREAM) {
        unsigned read = flac_decode_audio_block(psf, remaining);
        if (read == 0 && psf->flac_decoder_state != FLAC__DECODER_END_OF_STREAM) {
            break;
        }
        bytes_read += read;
        remaining -= read;
    }

    return bytes_read;
}

unsigned flac_decoder_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_read = 0;
    FLAC__StreamDecoder *decoder = psf->decoder;
    FLAC__StreamDecoderState state;
    FLAC__bool is_last_block;
    FLAC__uint64 sample_counter;

    if (!decoder)
        return 0;

    state = FLAC__stream_decoder_get_state(decoder);
    if (state != FLAC__STREAM_DECODER_SEARCHING_FOR_METADATA &&
        state != FLAC__STREAM_DECODER_READING_METADATA &&
        state != FLAC__STREAM_DECODER_DECODING) {
        psf_log_printf(psf, "FLAC decoder not in a valid state.\n");
        return 0;
    }

    while (bytes_read < len) {
        FLAC__int32 *buffer;
        unsigned sample_count;
        unsigned samples_per_frame = 0;
        unsigned bytes_remaining = len - bytes_read;

        if (!FLAC__stream_decoder_get_decode_position(decoder, &sample_counter)) {
            psf_log_printf(psf, "Could not get decode position.\n");
            return bytes_read;
        }

        if (!FLAC__stream_decoder_get_last_block(decoder, &is_last_block)) {
            psf_log_printf(psf, "Could not get last block status.\n");
            return bytes_read;
        }

        if (is_last_block)
            break;

        buffer = psf->buffer;
        sample_count = bytes_remaining / (psf->frame.size * sizeof(FLAC__int32));
        if (sample_count > 0) {
            if (!FLAC__stream_decoder_read(decoder, &buffer, &sample_count)) {
                state = FLAC__stream_decoder_get_state(decoder);
                psf_log_printf(psf, "Error decoding audio: %s\n", FLAC__StreamDecoderStateString[state]);
                psf->decoder = NULL;
                break;
            }
            bytes_read += sample_count * psf->frame.size * sizeof(FLAC__int32);
        }

        if (sample_count == 0)
            break;
    }

    return bytes_read;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned total_read = 0;
    FLAC__StreamDecoderState decoder_state;

    if (!psf || len == 0)
        return 0;

    decoder_state = FLAC__stream_decoder_get_state(psf->flac_decoder);
    if (decoder_state != FLAC__STREAM_DECODER_OK)
        psf_log_printf(psf, "FLAC decoder in invalid state: %s\n", FLAC__StreamDecoderStateString[decoder_state]);

    while (total_read < len && !psf->end_of_stream) {
        FLAC__uint64 frame_offset;
        size_t bytes_to_read = len - total_read;
        const FLAC__byte *buffer;

        if (psf->flac_decoder == NULL || !FLAC__stream_decoder_get_input_buffer(psf->flac_decoder, &buffer, &bytes_to_read))
            break;

        if (bytes_to_read > 0) {
            memcpy((char *)psf->data + total_read, buffer, bytes_to_read);
            total_read += bytes_to_read;
        }

        if (!FLAC__stream_decoder_process_single(psf->flac_decoder))
            break;
    }

    if (decoder_state != FLAC__STREAM_DECODER_OK)
        psf->frame = NULL;

    return total_read;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_read = 0;
    FLAC__StreamDecoderState decoder_state;
    FLAC__StreamDecoder *decoder = psf->decoder.flac.decoder;

    if (psf->decoder.flac.frame_remaining > 0) {
        if (psf->decoder.flac.frame_remaining > len)
            psf->decoder.flac.frame_remaining = len;

        memcpy(psf->read_ptr, psf->decoder.flac.frame_buffer, psf->decoder.flac.frame_remaining);
        psf->read_ptr += psf->decoder.flac.frame_remaining;
        bytes_read += psf->decoder.flac.frame_remaining;
        len -= psf->decoder.flac.frame_remaining;
        psf->decoder.flac.frame_remaining = 0;
    }

    while (len > 0) {
        decoder_state = FLAC__stream_decoder_get_state(decoder);
        if (decoder_state != FLAC__STREAM_DECODER_SEARCHING_FOR_METADATA &&
            decoder_state != FLAC__STREAM_DECODER_READING_METADATA &&
            decoder_state != FLAC__STREAM_DECODER_DECoding) {
            break;
        }

        if (FLAC__stream_decoder_process_single(decoder) == false) {
            psf_log_printf(psf, "FLAC: Error decoding audio data\n");
            psf->decoder.flac.frame = NULL;
            break;
        }

        if (psf->decoder.flac.frame_remaining <= 0)
            continue;

        if (psf->decoder.flac.frame_remaining > len)
            psf->decoder.flac.frame_remaining = len;

        memcpy(psf->read_ptr, psf->decoder.flac.frame_buffer, psf->decoder.flac.frame_remaining);
        psf->read_ptr += psf->decoder.flac.frame_remaining;
        bytes_read += psf->decoder.flac.frame_remaining;
        len -= psf->decoder.flac.frame_remaining;
        psf->decoder.flac.frame_remaining = 0;
    }

    return bytes_read;
}
